impl<T> JoinHandle<T>
pub fn abort_handle(&self) -> AbortHandle
```

---

`T` = `()`

---

Returns a new `AbortHandle` that can be used to remotely abort this task.

Awaiting a task cancelled by the `AbortHandle` might complete as usual if the task was
already completed at the time it was cancelled, but most likely it
will fail with a [cancelled] `JoinError`.

```rust
use tokio::{time, task};

let mut handles = Vec::new();

handles.push(tokio::spawn(async {
   time::sleep(time::Duration::from_secs(10)).await;
   true
}));

handles.push(tokio::spawn(async {
   time::sleep(time::Duration::from_secs(10)).await;
   false
}));

let abort_handles: Vec<task::AbortHandle> = handles.iter().map(|h| h.abort_handle()).collect();

for handle in abort_handles {
    handle.abort();
}

for handle in handles {
    assert!(handle.await.unwrap_err().is_cancelled());
}
```

[cancelled]: https://docs.rs/tokio/1.53.2/tokio/runtime/task/error/struct.JoinError.html#method.is_cancelled

